@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /**
     * A claim as the screen shows it; the amount is given with exactly two decimals, as is the due
     * fixed when it was settled (null while it is not settled, or if its grade had no rate then); openedBy
     * is who opened it (null while a draft); stated is whether its person's last statement binds it, to
     * statedDue (null if it had no figure then, when it stays n/a, or while PENDING, when no statement binds it); corrects is the number of the claim a correction corrects (null
     * on any other claim); deferredUntil is the day it was deferred until (null if never deferred); log is its status log, oldest first;
     * proofs is how many proofs have been given for it; splitFrom is the number of the claim it was split off (null
     * on any other claim); lockedBy is who has its editor open, locking it for other users (null when no one has);
     * lateEntry is whether it was added while its period was soft-closed.
     */
    public record ClaimView(long id, long personId, String amount, LocalDate date, String note, ClaimStatus status,
            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
            LocalDate dueBy, LocalDate deferredUntil, List<LogLine> log, int proofs, String splitFrom,
            String lockedBy, boolean lateEntry) {

        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getBoundDue() == null ? null : claim.getBoundDue().toPlainString(), claim.getCorrects(),
                    claim.getDueBy(), claim.getDeferredUntil(), claim.getLog().stream().map(LogLine::of).toList(),
                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(), claim.isLateEntry());
        }
    }

            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(claims.resettle(sheetId, user, id));
    }

    @PutMapping("/claims/{id}/defer")
    public ClaimView defer(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody Deferral request) {
        return ClaimView.of(claims.defer(sheetId, user, id, request.until()));
    }

    @PutMapping("/claims/{id}/date")
    public ClaimView redate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody Redating request) {
        return ClaimView.of(claims.redate(sheetId, user, id, request.date()));
    }

    @PostMapping("/claims/{id}/proofs")
    public ClaimView addProof(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(claims.addProof(sheetId, user, id));
    }

    @PutMapping("/claims/{id}/person")
        return changed;
    }

    /** Defer an OPEN claim until a day after the sheet's today: until the sheet's today reaches that day it counts
     *  in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim that
     *  is not OPEN, a day not after today and a claim due by inside a closed period. */
    @Transactional
    public Claim defer(String sheetId, String user, long id, LocalDate until) {
        sheets.load(sheetId, user);
        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
        refuseIfClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can");
        }
        if (!until.isAfter(sheet.getToday())) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A claim is deferred to a day after today");
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
        Rollup.Figures before = rollup.of(sheetId);
        claim.setDeferredUntil(until);
        Claim deferred = claims.saveAndFlush(claim);
        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_DEFERRED", user, person, deferred, deferred.getNumber()) + " until=" + until);
        rollup.recordChanges(sheetId, user, before);
        return deferred;
    }

    /** A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed, and with it its period and its
     *  number, and a figure a statement binds it to stays bound. Refused for anyone but a steward, a claim in any
        }
    }

    /** Raise a claim's proofs count by one. Refused for a SETTLED or VOID claim and one due by inside a closed
     *  period. */
    @Transactional
    public Claim addProof(String sheetId, String user, long id) {
        sheets.load(sheetId, user);
        sheetStore.findLockedById(sheetId).orElseThrow();
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
        refuseIfClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be given a proof");
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
        claim.addProof();
        Claim proven = claims.saveAndFlush(claim);
        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_PROOF_ADDED", user, person, proven, proven.getNumber())
                + " proofs=" + proven.getProofs());
        return proven;
    }

    /** A steward approves a PENDING claim: it becomes SETTLED, its due fixed as it is at this moment (its live
     *  figure with the late charge it has gained). Refused for a clerk, for the user who opened the claim, for a
     *  claim that is not PENDING and for one due by inside a closed period. */
  /** The figure the claim had at its person's last statement, while bound by it, with exactly two
   *  decimals; null when not bound, while PENDING (it then follows the rate), or if it had no figure then (it stays n/a). */
  statedDue: string | null;
  /** The number of the SETTLED claim of the same person a correction (a negative amount) corrects; null on
   *  any other claim. */
  corrects: string | null;
  /** The day the claim is due by (yyyy-mm-dd): fixed when it was added, from its date and the terms of its
   *  person's grade in force then. */
  dueBy: string;
  /** The day the claim was deferred until (yyyy-mm-dd); null if it was never deferred. */
  deferredUntil: string | null;
  /** The claim's status log, oldest first: a line for each status it has had, the DRAFT it was added as first. */
  log: ClaimLogLine[];
  /** How many proofs have been given for the claim. */
  proofs: number;
  /** The number of the claim this one was split off; null on any other claim. */
  splitFrom: string | null;
  /** The signed-in name of the user who has the claim's editor open, locking it for others; null when no one has. */
  lockedBy: string | null;
  /** Whether the claim was added while the period its due-by is in was soft-closed. */
  lateEntry: boolean;
  redate(sheetId: string, id: number, date: string): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/date`, { date });
  }

  /** Raise a claim's proofs count by one; refused for a SETTLED or VOID claim. */
  addProof(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/claims/${id}/proofs`, {});
  }

  /** A steward approves a PENDING claim: it is SETTLED, its due fixed as it is now. */
  approve(sheetId: string, id: number): Observable<ClaimView> {

